def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    if n == 1:
        return 'D' if last_opp == 'D' else 'C'

    prev_my = history[-2][0]

    opp_c = 0
    d_resp_c = 0
    d_resp_d = 0
    c_resp_d = 0

    for i in range(n):
        a, b = history[i]
        if b == 'C':
            opp_c += 1
        if i > 0:
            pa = history[i - 1][0]
            if pa == 'D':
                if b == 'C':
                    d_resp_c += 1
                else:
                    d_resp_d += 1
            else:
                if b == 'D':
                    c_resp_d += 1

    opp_rate = opp_c / float(n)

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_d_streak += 1
        else:
            break

    my_d_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_d_streak += 1
        else:
            break

    w = min(n, 10)
    recent_c = 0
    for i in range(n - w, n):
        if history[i][1] == 'C':
            recent_c += 1

    w5 = min(n, 5)
    recent5_c = 0
    for i in range(n - w5, n):
        if history[i][1] == 'C':
            recent5_c += 1

    if opp_rate < 0.18:
        return 'D'
    if recent_c == 0 and opp_rate < 0.35:
        return 'D'
    if opp_d_streak >= 7 and opp_rate < 0.5:
        return 'D'

    if prev_my == 'D':
        if last_opp == 'C':
            if d_resp_c >= d_resp_d + 1 or opp_rate > 0.7 or recent5_c >= 3:
                return 'D'
            if rng.random() < 0.25:
                return 'D'
            return 'C'
        else:
            if last_me == 'C' and opp_d_streak >= 3:
                return 'D'
            if opp_rate > 0.35 or recent_c >= 2:
                return 'C'
            return 'D'

    if last_opp == 'D':
        if last_me == 'C' and opp_d_streak >= 3:
            return 'D'
        if c_resp_d <= 1 and opp_rate > 0.82 and opp_d_streak <= 1 and recent5_c >= 3:
            return 'C'
        if c_resp_d <= 2 and opp_rate > 0.65 and opp_d_streak <= 2 and recent_c >= 7:
            if rng.random() < 0.2:
                return 'C'
        return 'D'

    if d_resp_c > d_resp_d:
        if opp_c == n or opp_rate > 0.85:
            return 'D'
        if my_d_streak < 3:
            if rng.random() < 0.55:
                return 'D'
        else:
            if opp_rate > 0.5:
                return 'D' if rng.random() < 0.2 else 'C'
            return 'C'
        return 'C'

    if opp_c == n and my_d_streak == 0 and 45 <= n <= 85:
        if rng.random() < 0.55:
            return 'D'

    if d_resp_c > d_resp_d and opp_rate > 0.75 and c_resp_d <= max(2, n // 25):
        return 'D'

    return 'C'
